#!/usr/bin/env node
// Read-only intake verifier for genuine GeoImpact-CI V4/V5 reports supplied from OUTSIDE the repository.
//
//   node geoimpact-copilot/evaluation/external/intake.mjs DIRECTORY
//
// It checks the paperwork a person wrote (NAME.intake.json) against the report bytes, refuses anything
// that is, or is byte- or content-identical to, a synthetic report this repository generates, and
// refuses reports whose origin, rights or verification are missing or attributed to an automated system.
// It never fills in a field, never marks a report verified, and never copies or modifies a report.
import Ajv from "ajv";
import { createHash } from "node:crypto";
import { readFile, readdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { reviewerIdentityProblems } from "../../lib/review.mjs";
import { loadReportFile } from "../../lib/report.mjs";
import { generateReports, range } from "../synthetic/generator.mjs";

const here = new URL("./", import.meta.url);
const fixturesDir = new URL("../../fixtures/", import.meta.url);
const sha256 = (data) => createHash("sha256").update(data).digest("hex");

/** Digest of the parsed value with object keys sorted, so a re-indented or re-ordered copy still matches. */
export function canonicalDigest(value) {
  const sort = (item) => (Array.isArray(item) ? item.map(sort) : item && typeof item === "object" ? Object.fromEntries(Object.keys(item).sort().map((key) => [key, sort(item[key])])) : item);
  return sha256(JSON.stringify(sort(value)));
}

// A target for "small, diverse". It is a floor for the first look at real reports, not a statistical sample.
export const DIVERSITY_TARGET = { minimum_reports: 8, minimum_per_version: 3, minimum_per_verdict: 2, size_classes: ["small", "medium", "large"], minimum_distinct_regions: 3 };

const placeholderEngine = /\b(synthetic|placeholder|fixture|example|fake|dummy|test|mock)\b/i;
const today = () => new Date().toISOString().slice(0, 10);

async function* walk(directoryUrl) {
  for (const entry of await readdir(directoryUrl, { withFileTypes: true })) {
    const child = new URL(entry.name + (entry.isDirectory() ? "/" : ""), directoryUrl);
    if (entry.isDirectory()) yield* walk(child);
    else if (entry.name.endsWith(".json")) yield child;
  }
}

let corpus = null;
/** Every report this repository ships or can generate: raw-byte digests and canonical-content digests. */
export async function knownSyntheticCorpus() {
  if (corpus) return corpus;
  const raw = new Set();
  const canonical = new Set();
  for await (const url of walk(fixturesDir)) {
    const bytes = await readFile(url);
    raw.add(sha256(bytes));
    try { canonical.add(canonicalDigest(JSON.parse(bytes.toString("utf8")))); } catch { /* not JSON */ }
  }
  const manifest = JSON.parse(await readFile(new URL("../synthetic/manifest.json", import.meta.url), "utf8"));
  const groups = [...manifest.splits.development.groups, ...manifest.splits.held_out.groups, { first: 500, count: 4 }];
  for (const group of groups) {
    for (const { report } of generateReports(range(group.first, group.count), group.overrides ?? {})) {
      canonical.add(canonicalDigest(report));
      raw.add(sha256(JSON.stringify(report)));
      raw.add(sha256(`${JSON.stringify(report, null, 2)}\n`));
    }
  }
  corpus = { raw, canonical };
  return corpus;
}

const validateRecord = new Ajv({ allErrors: true, strict: false }).compile(JSON.parse(await readFile(new URL("./intake-record.schema.json", here), "utf8")));

const realDate = (text) => typeof text === "string" && /^\d{4}-\d{2}-\d{2}$/.test(text) && new Date(`${text}T00:00:00Z`).toISOString().slice(0, 10) === text;

/** Pure check of one record against the report bytes. Returns the problems found; empty means the paperwork is in order. */
export function recordProblems(record, { bytes, report, known, now = today() }) {
  if (!validateRecord(record)) return validateRecord.errors.map((error) => `record ${error.instancePath || "/"} ${error.message}`).slice(0, 6);
  const problems = [];
  if (sha256(bytes) !== record.report_sha256) problems.push("report_sha256 does not match the report bytes");
  if (known.raw.has(sha256(bytes)) || known.canonical.has(canonicalDigest(report))) problems.push("report is identical to a synthetic report generated by or shipped with this repository; it cannot be presented as genuine");
  if (record.origin.kind !== "genuine_geoimpact_ci_run") problems.push(`origin.kind is ${record.origin.kind}; only genuine_geoimpact_ci_run is admissible`);
  if (record.origin.real_input_data !== true) problems.push("origin.real_input_data must be true: a GeoImpact-CI run on invented inputs is a synthetic report");
  if (record.origin.input_hashes_match_report !== true) problems.push("origin.input_hashes_match_report must be true: the producer must confirm the report's input hashes against the inputs it used");
  if (!realDate(record.origin.run_date) || record.origin.run_date > now) problems.push("origin.run_date must be a real date that is not in the future");
  if (record.diversity.report_version !== String(report.report_version)) problems.push(`diversity.report_version ${record.diversity.report_version} does not match the report (${report.report_version})`);
  if (record.diversity.verdict !== report.verdict) problems.push(`diversity.verdict ${record.diversity.verdict} does not match the report (${report.verdict})`);
  if (String(report.report_version) === "5") {
    const engine = report.provenance?.engine ?? {};
    if (engine.geoimpact_ci !== record.origin.geoimpact_ci_version) problems.push(`origin.geoimpact_ci_version ${JSON.stringify(record.origin.geoimpact_ci_version)} does not match provenance.engine.geoimpact_ci ${JSON.stringify(engine.geoimpact_ci)}`);
    for (const [name, value] of Object.entries(engine)) if (placeholderEngine.test(String(value))) problems.push(`provenance.engine.${name} looks like a placeholder (${JSON.stringify(value)})`);
  }
  if (record.status === "admitted") {
    for (const kind of ["rights", "provenance"]) {
      const check = record.verification[kind];
      if (check.status !== "verified") problems.push(`verification.${kind} is not verified`);
      else {
        problems.push(...reviewerIdentityProblems(check.verified_by).map((problem) => `verification.${kind}: ${problem.replace("reviewed_by", "verified_by")}`));
        if (!realDate(check.verified_on) || check.verified_on > now) problems.push(`verification.${kind}.verified_on must be a real date that is not in the future`);
        if (!check.method || check.method.trim().length < 10) problems.push(`verification.${kind}.method must say how it was verified`);
      }
    }
    if (!realDate(record.rights.evidence_retrieved_on)) problems.push("rights.evidence_retrieved_on must be a real date");
  } else if (record.status === "rejected" && !record.rejection_reason) {
    problems.push("a rejected record must say why");
  }
  return problems;
}

export async function checkIntake(directory, { now = today(), onlyThirdPartyPermitted = false } = {}) {
  const names = (await readdir(directory)).filter((name) => name.endsWith(".intake.json")).sort();
  const reports = (await readdir(directory)).filter((name) => name.endsWith(".report.json")).sort();
  if (names.length === 0 && reports.length === 0) {
    return { status: "no_reports_supplied", note: "No genuine report has been supplied. Nothing was invented or substituted. The Sonnet experiment, and any claim about real-world accuracy, stay on HOLD.", reports: [], admitted: 0, gate_passed: true };
  }
  const known = await knownSyntheticCorpus();
  const results = [];
  for (const file of names) {
    let record;
    try { record = JSON.parse(await readFile(new URL(file, new URL(`file://${directory.replaceAll("\\", "/").replace(/\/?$/, "/")}`)), "utf8")); } catch (error) { results.push({ file, outcome: "rejected_intake", problems: [`unreadable record: ${error.message}`] }); continue; }
    const reportName = typeof record?.report_file === "string" ? record.report_file : null;
    let bytes; let report;
    try {
      bytes = await readFile(`${directory}/${reportName}`);
      report = await loadReportFile(`${directory}/${reportName}`);
    } catch (error) { results.push({ file, outcome: "rejected_intake", problems: [`report cannot be loaded as a valid V4/V5 report: ${String(error.message).slice(0, 160)}`] }); continue; }
    const problems = recordProblems(record, { bytes, report, known, now });
    const outcome = problems.length ? "rejected_intake" : record.status === "admitted" ? "admitted" : record.status === "rejected" ? "rejected_by_record" : "candidate";
    results.push({ file, report_file: reportName, report_sha256: outcome === "admitted" ? record.report_sha256 : null, outcome, problems, status: record?.status, report_version: record?.diversity?.report_version, verdict: record?.diversity?.verdict, size_class: record?.diversity?.size_class, region: record?.diversity?.region_description, third_party_model_permitted: outcome === "admitted" && record.rights.may_be_sent_to_third_party_model === true });
  }
  for (const report of reports) if (!names.includes(report.replace(".report.json", ".intake.json"))) results.push({ file: report, outcome: "rejected_intake", problems: ["report has no NAME.intake.json; it cannot be used"] });
  // With onlyThirdPartyPermitted, a report without explicit permission to go to a third-party model is not counted.
  const admitted = results.filter((item) => item.outcome === "admitted" && (!onlyThirdPartyPermitted || item.third_party_model_permitted === true));
  const count = (key, value) => admitted.filter((item) => item[key] === value).length;
  const diversity = {
    admitted: admitted.length,
    by_version: { 4: count("report_version", "4"), 5: count("report_version", "5") },
    by_verdict: { PASS: count("verdict", "PASS"), BLOCK: count("verdict", "BLOCK") },
    by_size: Object.fromEntries(DIVERSITY_TARGET.size_classes.map((size) => [size, count("size_class", size)])),
    distinct_regions: new Set(admitted.map((item) => item.region)).size
  };
  diversity.target_met = diversity.admitted >= DIVERSITY_TARGET.minimum_reports &&
    Object.values(diversity.by_version).every((n) => n >= DIVERSITY_TARGET.minimum_per_version) &&
    Object.values(diversity.by_verdict).every((n) => n >= DIVERSITY_TARGET.minimum_per_verdict) &&
    DIVERSITY_TARGET.size_classes.every((size) => diversity.by_size[size] >= 1) &&
    diversity.distinct_regions >= DIVERSITY_TARGET.minimum_distinct_regions;
  return { status: "supplied", reports: results, admitted: admitted.length, diversity, diversity_target: DIVERSITY_TARGET, gate_passed: results.every((item) => item.outcome !== "rejected_intake") };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === fileURLToPath(new URL(`file://${process.argv[1].replaceAll("\\", "/")}`))) {
  const directory = process.argv[2];
  const onlyPermitted = process.argv.includes("--third-party-model-only");
  if (!directory) {
    process.stderr.write("usage: node geoimpact-copilot/evaluation/external/intake.mjs DIRECTORY\n");
    process.exitCode = 2;
  } else {
    const result = await checkIntake(directory, { onlyThirdPartyPermitted: onlyPermitted });
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    process.exitCode = result.gate_passed ? 0 : 1;
  }
}
